//! Parity: dtype parsing matches `meerschaum.utils.dtypes` (`fixtures/dtypes.json`, generated by
//! `fixtures/gen_dtypes.py`).

mod common;

use meerschaum_core::Value;
use meerschaum_core::dtypes::{
    GeometrySpec, PrecisionUnit, Srid, are_dtypes_equal, get_geometry_type_srid, is_dtype_numeric,
    is_dtype_special, parse_numeric_precision_scale,
};

#[test]
fn are_dtypes_equal_matches_python() {
    let fixture = common::load_fixture("dtypes.json");
    let pairs = fixture
        .get("are_dtypes_equal")
        .and_then(Value::as_list)
        .unwrap();
    assert!(pairs.len() > 1000);
    for pair in pairs {
        let p = pair.as_list().unwrap();
        let (l, r) = (p[0].as_str().unwrap(), p[1].as_str().unwrap());
        assert_eq!(
            are_dtypes_equal(l, r),
            p[2].as_bool().unwrap(),
            "are_dtypes_equal({l:?}, {r:?})"
        );
    }
    for (d, v) in fixture
        .get("is_dtype_special")
        .and_then(Value::as_map)
        .unwrap()
    {
        assert_eq!(
            is_dtype_special(d),
            v.as_bool().unwrap(),
            "is_dtype_special({d:?})"
        );
    }
    for (d, v) in fixture
        .get("is_dtype_numeric")
        .and_then(Value::as_map)
        .unwrap()
    {
        assert_eq!(
            is_dtype_numeric(d),
            v.as_bool().unwrap(),
            "is_dtype_numeric({d:?})"
        );
    }
}

#[test]
fn geometry_matches_python() {
    let fixture = common::load_fixture("dtypes.json");
    for g in fixture.get("geometry").and_then(Value::as_list).unwrap() {
        let dtype = g.get("dtype").and_then(Value::as_str).unwrap();
        let result = get_geometry_type_srid(dtype, "geometry", Srid::Code(0));
        if g.get("error").is_some() {
            assert!(result.is_err(), "{dtype} should fail");
            continue;
        }
        let (typ, srid) = result.unwrap();
        assert_eq!(
            Some(typ.as_str()),
            g.get("type").and_then(Value::as_str),
            "{dtype}"
        );
        let expected_srid = match g.get("srid").unwrap() {
            Value::Int(i) => Srid::Code(*i),
            Value::Str(s) => Srid::Authority(s.clone()),
            other => panic!("unexpected srid {other:?}"),
        };
        assert_eq!(srid, expected_srid, "{dtype}");
        let spec = GeometrySpec::parse(dtype).unwrap().unwrap();
        assert_eq!(
            Some(spec.canonical().as_str()),
            g.get("canonical").and_then(Value::as_str),
            "{dtype}"
        );
    }
}

#[test]
fn numeric_and_precision_units_match_python() {
    let fixture = common::load_fixture("dtypes.json");
    for (d, v) in fixture
        .get("numeric_precision_scale")
        .and_then(Value::as_map)
        .unwrap()
    {
        let l = v.as_list().unwrap();
        let expected = l[0].as_i64().zip(l[1].as_i64());
        assert_eq!(parse_numeric_precision_scale(d), expected, "{d}");
    }
    for (u, v) in fixture
        .get("next_precision_unit")
        .and_then(Value::as_map)
        .unwrap()
    {
        let unit = PrecisionUnit::parse(u).unwrap();
        for (key, decrease) in [("True", true), ("False", false)] {
            let expected = v.get(key).and_then(Value::as_str);
            assert_eq!(
                unit.next(decrease).map(|n| n.name()),
                expected,
                "get_next_precision_unit({u:?}, decrease={decrease})"
            );
        }
    }
}
